/** public/data/state.json, generated by scripts/arc.mjs. */
export type Machine = [handle: string, joinDay: number, game: number, neon: number];
export interface Episode { day: number; date?: string; title: string; summary?: string; links?: Partial<Record<"instagram" | "tiktok" | "youtube", string>> }
export interface GameState {
  version: 1;
  updatedAt: string;
  day: number;
  series: { name: string; tagline: string; rule: string; account: string };
  links: { latestEpisode?: string; instagram?: string; tiktok?: string; youtube?: string };
  episodes: Episode[];
  totals: { machines: number; newToday: number; days: number };
  preview: { headline: string; stat: number; statLabel: string; top: { label: string; sub: string }[] };
  games: string[];
  /** Machine number = index + 1. Empty handle = opted out. */
  machines: Machine[];
}
